function solve(input) {
  const { nums, k } = input;
  const count = new Map();
  for (const n of nums) count.set(n, (count.get(n) || 0) + 1);
  const sorted = [...count.entries()].sort((a, b) => b[1] - a[1]);
  return sorted.slice(0, k).map(e => e[0]);
}
